const services = $input.item.json.services;
const locations = $input.item.json.locations;
const tags = $input.item.json.tags;

// Initialize array to hold search patterns
let patterns = [];

// Pattern 1: service + location (e.g., plumbertampa)
for (const service of services) {
  for (const location of locations) {
    patterns.push({
      pattern: service + location,
      service: service,
      location: location,
      tag: '',
      patternType: 'service-location'
    });
  }
}

// Pattern 2: location + service (e.g., tampaplumber)
for (const location of locations) {
  for (const service of services) {
    patterns.push({
      pattern: location + service,
      service: service,
      location: location,
      tag: '',
      patternType: 'location-service'
    });
  }
}

// Pattern 3: service + location + tag (e.g., plumbertampapro)
for (const service of services) {
  for (const location of locations) {
    for (const tag of tags) {
      patterns.push({
        pattern: service + location + tag,
        service: service,
        location: location,
        tag: tag,
        patternType: 'service-location-tag'
      });
    }
  }
}

// Pattern 4: service + tag + location (e.g., plumberprotampa)
for (const service of services) {
  for (const tag of tags) {
    for (const location of locations) {
      patterns.push({
        pattern: service + tag + location,
        service: service,
        location: location,
        tag: tag,
        patternType: 'service-tag-location'
      });
    }
  }
}

// Return as array of items
return patterns.map(p => ({ json: p }));

// Process the results and rank domains
const item = $input.item.json;

// Create full domain name with TLD
const domainWithTLD = item.pattern + '.com';

// Initialize ranking factors
let score = 0;
let availability = false;
let isExpired = false;
let isAuction = false;
let price = 0;
let status = 'unknown';

// Process GoDaddy data if exists
if (item.hasOwnProperty('available')) {
  availability = item.available;
  if (item.hasOwnProperty('price')) price = item.price;
}

// Process auction data if exists
if (item.hasOwnProperty('results') && Array.isArray(item.results)) {
  const matchingDomain = item.results.find(d => d.name === domainWithTLD);
  if (matchingDomain) {
    isAuction = true;
    price = matchingDomain.price || price;
    status = 'auction';
  }
}

// Process Namecheap data if exists
if (item.hasOwnProperty('CommandResponse') && 
    item.CommandResponse.hasOwnProperty('DomainCheckResult')) {
  availability = item.CommandResponse.DomainCheckResult.hasOwnProperty('Available') ? 
    item.CommandResponse.DomainCheckResult.Available === 'true' : availability;
}

// Calculate domain quality score
score += item.pattern.length <= 15 ? 30 : 0;  // Shorter domains get bonus
score += item.pattern.match(/[0-9-]/) ? -10 : 0;  // Penalize numbers and hyphens

// Pattern type scoring
switch(item.patternType) {
  case 'service-location':
    score += 25;
    break;
  case 'location-service':
    score += 20;
    break;
  case 'service-location-tag':
    score += 15;
    break;
  case 'service-tag-location':
    score += 10;
    break;
}

// Popular locations and services get bonus
const highValueLocations = ['newyork', 'losangeles', 'chicago', 'houston', 'dallas', 'seattle'];
const highValueServices = ['plumber', 'hvac', 'attorney', 'doctor', 'dentist'];

if (highValueLocations.includes(item.location)) score += 15;
if (highValueServices.includes(item.service)) score += 15;

// Auction domains might be valuable
if (isAuction) score += 10;

// Available domains with high score are ideal
if (availability) {
  status = 'available';
  score += 20;
} else if (isExpired) {
  status = 'expired';
  score += 15;
} else if (isAuction) {
  status = 'auction';
  score += 10;
} else {
  status = 'taken';
}

// Return enhanced item with scoring
return {
  domain: domainWithTLD,
  pattern: item.pattern,
  service: item.service,
  location: item.location,
  tag: item.tag,
  patternType: item.patternType,
  score: score,
  status: status,
  price: price,
  availability: availability,
  isAuction: isAuction,
  isExpired: isExpired,
  timestamp: new Date().toISOString()
};

