const raw = $json.output || $json.message || $json.text;

if (!raw) {
  throw new Error("Missing AI output text.");
}

const match = raw.match(/```json\s*([\s\S]*?)```/);
if (!match) {
  throw new Error("No ```json code block found.");
}

const jsonString = match[1].trim();

try {
  const parsed = JSON.parse(jsonString);

  // ✅ Return as a proper n8n item
  return [{ json: parsed }];
} catch (err) {
  throw new Error("Workflow JSON parse failed: " + err.message);
}

// Parse the OpenAI response
const responseText = $input.item.json.text;

// Extract ideas
const ideas = [];

// First, try to extract structured ideas using regex
const ideaRegex = /(.*?)\n([\s\S]*?)(?=\n(?:\d+\.|$))/g;
let match;

while ((match = ideaRegex.exec(responseText)) !== null) {
  // Extract title and description
  const fullIdea = match[0].trim();
  const titleMatch = fullIdea.match(/^\d+\.\s*(.*)/);

  if (titleMatch) {
    const title = titleMatch[1].trim();
    // Get everything after the title
    const description = fullIdea.substring(fullIdea.indexOf('\n')).trim();

    ideas.push({
      title,
      description
    });
  }
}

// If we couldn't parse using regex, try a simpler approach
if (ideas.length === 0) {
  const lines = responseText.split('\n');
  let currentTitle = '';
  let currentDescription = '';

  for (const line of lines) {
    if (line.match(/^\d+\.\s*/)) {
      // This is a new idea title
      if (currentTitle && currentDescription) {
        ideas.push({
          title: currentTitle,
          description: currentDescription.trim()
        });
      }

      currentTitle = line.replace(/^\d+\.\s*/, '');
      currentDescription = '';
    } else if (currentTitle) {
      currentDescription += line + '\n';
    }
  }

  // Add the last idea
  if (currentTitle && currentDescription) {
    ideas.push({
      title: currentTitle,
      description: currentDescription.trim()
    });
  }
}

// If we still have no ideas, create a fallback
if (ideas.length === 0) {
  ideas.push({
    title: "AI-Generated Workflow Ideas",
    description: responseText.trim()
  });
}

// Return the ideas
return { ideas };

