function calculateCompatibilityScore(nodes) {
  if (nodes.length <= 1) return 10; // Single node is always compatible with itself

  // Basic compatibility logic
  let score = 8; // Start with high compatibility
  let hasTrigger = false;

  // Check for at least one trigger node
  for (const node of nodes) {
    if (nodeDatabase[node]?.triggerNode) {
      hasTrigger = true;
      break;
    }
  }

  // Reduce score if no trigger nodes found
  if (!hasTrigger && nodes.length > 1) {
    score -= 3;
  }

  // Enhance score for common pairings
  for (let i = 0; i < nodes.length; i++) {
    for (let j = i + 1; j < nodes.length; j++) {
      const nodeA = nodes[i];
      const nodeB = nodes[j];

      if (nodeDatabase[nodeA]?.commonPairings.includes(nodeB) || 
          nodeDatabase[nodeB]?.commonPairings.includes(nodeA)) {
        score += 1;
