      technicalImplementation: `Webhook node receives POST requests, Set node formats the data, ${nodes.includes("Google Sheets") ? "Google Sheets" : "Airtable"} node stores the information with timestamps.`,
      businessValue: "Centralized event tracking across systems, audit trail creation, enables data-driven decisions based on external events.",
      extensionPossibilities: "Add notification system for critical events, data visualization dashboard, automated reporting."
    });
  }

  // Check for Slack + any trigger
  if (nodes.includes("Slack") && (nodes.includes("Gmail") || nodes.includes("Webhook") || nodes.includes("HTTP Request"))) {
    const triggerNode = nodes.includes("Gmail") ? "Gmail" : (nodes.includes("Webhook") ? "Webhook" : "HTTP Request");
    ideas.push({
      title: "Intelligent Notification System",
      description: `Create a smart notification system that processes ${triggerNode === "Gmail" ? "emails" : "incoming data"} and sends contextualized alerts to Slack.`,
      technicalImplementation: `${triggerNode} node triggers the workflow, Function node analyzes content and determines importance, Slack node sends targeted notifications to appropriate channels.`,
      businessValue: "Reduces information overload, ensures critical information reaches the right people, creates a centralized notification system.",
      extensionPossibilities: "Add time-based rules to prevent off-hours notifications, user preference settings, urgency classification."
    });
  }

  // Add generic ideas based on node types present

  // Data transformation idea
  if (nodes.includes("Function") || nodes.includes("Set")) {
    ideas.push({
      title: "Data Standardization & Enrichment",
      description: "Create a workflow that standardizes data formats and enriches records with additional information.",
      technicalImplementation: `${nodes.includes("Function") ? "Function" : "Set"} node to standardize formats and structure, HTTP Request node (if available) to enrich data from external sources, output to relevant storage or system.`,
      businessValue: "Improves data quality, enables better analytics, prepares data for use in multiple systems.",
      extensionPossibilities: "Add validation rules, error handling for incomplete data, multi-stage enrichment pipeline."
    });
  }

  // Check if we need more ideas
  while (ideas.length < 5) {
    ideas.push({
      title: "Custom Multi-System Integration",
      description: `Create a workflow that bridges ${nodes.join(" and ")} to enable seamless data flow between systems.`,
      technicalImplementation: "Configure each node with appropriate authentication and settings, use Function or Set nodes to transform data between formats as needed.",
      businessValue: "Eliminates manual data transfer, reduces errors, creates real-time information flow between systems.",
      extensionPossibilities: "Add error notification system, logging for audit purposes, conditional logic for advanced routing."
    });
  }

  return ideas.slice(0, 5); // Return at most 5 ideas
}

// Main analysis function
function analyzeNodes(nodes) {
  // Filter out unknown nodes
  const knownNodes = nodes.filter(node => nodeDatabase[node]);

  // If all nodes are unknown, return a helpful message
  if (knownNodes.length === 0 && nodes.length > 0) {
    return {
      metaAnalysis: {
        message: "The selected nodes are not in our database. Please try different nodes.",
        compatibilityScore: 0,
        complexity: "Unknown",
        capabilities: []
      },
      ideas: []
    };
  }

  // Calculate compatibility score
  const compatibilityScore = calculateCompatibilityScore(knownNodes);

  // Determine overall complexity
  let complexityLevels = knownNodes.map(node => nodeDatabase[node].complexityLevel);
  let overallComplexity = "Beginner";
  if (complexityLevels.includes("Advanced")) {
    overallComplexity = "Advanced";
  } else if (complexityLevels.includes("Intermediate")) {
    overallComplexity = "Intermediate";
  }

  // Collect unique capabilities
  const capabilities = new Set();
  knownNodes.forEach(node => {
    nodeDatabase[node].capabilities.forEach(capability => capabilities.add(capability));
  });

  // Generate workflow ideas
  const ideas = generateWorkflowIdeas(knownNodes);

  return {
    metaAnalysis: {
      selectedNodes: knownNodes,
      compatibilityScore,
      complexity: overallComplexity,
      capabilities: Array.from(capabilities)
    },
    ideas
  };
}

// Process the input and generate results
